import{_ as o}from"./chunks/add_icon.D_Q72d6b.js";import{_ as t}from"./chunks/run_single_step_icon.DpLO-o8r.js";import{_ as c,o as n,c as d,a6 as a}from"./chunks/framework.mtgKxyez.js";const y=JSON.parse('{"title":"1. Software Master Mode","description":"","frontmatter":{},"headers":[],"relativePath":"en/advanced/1.md","filePath":"en/advanced/1.md"}'),i={name:"en/advanced/1.md"};function s(r,e,l,p,h,u){return n(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="_1-software-master-mode" tabindex="-1">1. Software Master Mode <a class="header-anchor" href="#_1-software-master-mode" aria-label="Permalink to &quot;1. Software Master Mode&quot;">​</a></h1><h2 id="vision-ocr-and-barcodes" tabindex="-1">Vision (OCR and Barcodes) <a class="header-anchor" href="#vision-ocr-and-barcodes" aria-label="Permalink to &quot;Vision (OCR and Barcodes)&quot;">​</a></h2><p>We have basically gone through the <code>Positioning</code> functions of <code>Vision</code>. In this chapter, we look at <code>Inspection</code>. Note that <code>Inspection</code> does not have a <code>Point</code> function like <code>Positioning</code>; it simply performs visual recognition.</p><p>Drag in an <code>Inspection</code> node and click its pencil icon to open the <code>Vision</code> editor. In <code>Vision Application Selection</code>, choose <code>AOI Recognition</code> → <code>Next</code>. Under this category, you can recognize text and numbers, which is OCR, read two-dimensional barcodes, read QR Codes, and so on.</p><p>In the left flow blocks, use the same setup method as before to set <code>Motion</code> and <code>Camera</code>. After setting them, click <img src="'+o+'" alt="Add flow icon" style="width:25px;display:inline;vertical-align:middle;margin:0 5px;"> under <code>Camera</code>. This enters the <code>Add Vision Flow</code> page. In the <code>Identify</code> category, you can find the functions mentioned earlier. Choose the target you want to recognize. The <code>Additional Functions</code> section can expand all functions. Click <code>OK</code>, and you can start setting that recognition task.</p><p>Using <code>Optical Character Recognition 2</code> as an example, the <code>Model Selection</code> dropdown on the right provides three options:</p><ul><li><code>Common</code>: numbers (<code>0</code> to <code>9</code>), uppercase Latin letters (<code>A</code> to <code>Z</code>), and symbols (<code>/</code>, <code>@</code>, <code>:</code>, <code>(</code>, <code>)</code>, <code>-</code>, <code>.</code>, <code>#</code>, <code>$</code>, <code>%</code>, <code>&amp;</code>, <code>*</code>, <code>+</code>, <code>&lt;</code>, <code>=</code>, <code>&gt;</code>)</li><li><code>Numeral</code>: numbers (<code>0</code> to <code>9</code>), plus <code>-</code> and <code>.</code></li><li><code>Universal</code>: numbers (<code>0</code> to <code>9</code>), uppercase and lowercase Latin letters (<code>A</code> to <code>Z</code>), and symbols (<code>/</code>, <code>@</code>, <code>:</code>, <code>(</code>, <code>)</code>, <code>-</code>, <code>.</code>, <code>#</code>, <code>$</code>, <code>%</code>, <code>&amp;</code>, <code>*</code>, <code>+</code>, <code>&lt;</code>, <code>=</code>, <code>&gt;</code>)</li></ul><p>The recognition result can be found in the variable list.</p><h2 id="ai" tabindex="-1">AI+ <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;AI+&quot;">​</a></h2><p>AI+ is actually very powerful, and it is almost guaranteed to appear in advanced finals. However, because of the YMSH robot arm environment, we cannot practice this part on the school arms. So in this chapter we only explain the concept. The detailed operation can only be learned in TM Robot&#39;s training course.</p><p>AI+ is a major category under <code>Vision</code>. It can do <strong>classification, object detection, semantic segmentation, anomaly detection, and instance segmentation</strong>. The one we use most often is <strong>classification</strong>. By taking several photos, it can do a simple form of machine learning, teach the machine to classify objects, and then run different flows according to the detection result.</p><h2 id="single-step-execution" tabindex="-1">Single-Step Execution <a class="header-anchor" href="#single-step-execution" aria-label="Permalink to &quot;Single-Step Execution&quot;">​</a></h2><p>When editing a program, you can click <img src="'+t+'" alt="Single-step execution icon" style="width:25px;display:inline;vertical-align:middle;margin:0 5px;"> at the top to enable <strong>single-step execution</strong>. Click the node you want to run, then use <code>PLAY</code> on the controller to execute it one step at a time. However, only some nodes support single-step execution. For example, <code>Set</code> cannot be executed this way.</p><p>A small trick: after creating a vision task, if you accidentally move to the workpiece position, or if you want to reset a <code>Point</code> based on Vision Base, the Vision Base position may shift because the workpiece position is different. In that case, use single-step execution to run <code>Vision</code> once. It will use the position seen during that execution, letting you set a new <code>Point</code> accurately without recreating the vision task.</p>',14)])])}const b=c(i,[["render",s]]);export{y as __pageData,b as default};
